284	<script>
285	import router from '@system.router'
286	import storage from '@system.storage'
287	// velaclaw 不在顶层 import：当前固件没编入 system.velaclaw feature
288	// （依赖 CONFIG_EXAMPLES_AI_AGENT_VELA），顶层 import 会在模块加载时就失败，
289	// 导致整个页面渲染不出来（黑屏）。改成用到时才取。
290	function getVelaclaw() {
291	  try {
292	    return require('@system.velaclaw')
293	  } catch (err) {
294	    console.warn('velaclaw feature 不可用:', err)
295	    return null
296	  }
297	}
298	
299	export default {
300	  data: {
301	    rideTime: '00:00:00',
302	    currentSpeed: '0.0',
303	    totalDistance: '0.0',
304	    avgSpeed: '0.0',
305	    calories: '0',
306	    statusText: '骑行中',
307	    statusClass: 'riding',
308	    isPaused: false,
309	    motionIcon: '🚶',
310	    motionText: '静止',
311	    progressPercent: 0,
312	    timeToRest: 60,
313	    showAlert: false,
314	    alertMessage: '',
315	    rideStartTime: null,
316	    rideSeconds: 0,
317	    timer: null
318	  },
319	
320	  onInit() {
321	    this.startRide()
322	  },
323	
324	  onDestroy() {
325	    if (this.timer) {
326	      clearInterval(this.timer)
327	    }
328	  },
329	
330	  startRide() {
331	    this.rideStartTime = Date.now()
332	    this.timer = setInterval(() => {
333	      if (!this.isPaused) {
334	        this.rideSeconds++
335	        this.updateRideTime()
336	        this.checkRestReminder()
337	      }
338	    }, 1000)
339	  },
340	
341	  updateRideTime() {
342	    const hours = Math.floor(this.rideSeconds / 3600)
343	    const minutes = Math.floor((this.rideSeconds % 3600) / 60)
344	    const seconds = this.rideSeconds % 60
345	    this.rideTime = `${String(hours).padStart(2, '0')}:${String(minutes).padStart(2, '0')}:${String(seconds).padStart(2, '0')}`
346	  },
347	
348	  checkRestReminder() {
349	    const minutesRiding = Math.floor(this.rideSeconds / 60)
350	    this.progressPercent = Math.min((minutesRiding / 60) * 100, 100)
351	    this.timeToRest = Math.max(60 - minutesRiding, 0)
352	
353	    if (minutesRiding > 0 && minutesRiding % 45 === 0) {
354	      this.showSafetyAlert('已连续骑行45分钟，建议休息一下')
355	    }
356	  },
357	
358	  togglePause() {
359	    this.isPaused = !this.isPaused
360	    this.statusText = this.isPaused ? '已暂停' : '骑行中'
361	    this.statusClass = this.isPaused ? 'ride-status-paused' : 'ride-status-riding'
362	  },
363	
364	  async stopRide() {
365	    if (this.timer) {
366	      clearInterval(this.timer)
367	    }
368	
369	    // 保存骑行记录
370	    await this.saveRideRecord()
371	
372	    // 生成 AI 复盘
373	    try {
374	      const velaclaw = getVelaclaw()
375	      if (!velaclaw) {
376	        console.warn('AI 功能需要固件启用 system.velaclaw feature')
377	        return
378	      }
379	      const result = await velaclaw.ask({
380	        query: `我刚完成一次骑行，时长${this.rideTime}，距离${this.totalDistance}公里，请给我一个简短的骑行复盘和建议`
381	      })
382	      console.log('AI Review:', result.reply)
383	      // TODO: 跳转到复盘页面显示结果
384	    } catch (err) {
385	      console.error('AI Review Error:', err)
386	    }
387	
388	    router.back()
389	  },
390	
391	  async saveRideRecord() {
392	    const record = {
393	      startTime: this.rideStartTime,
394	      endTime: Date.now(),
395	      duration: this.rideSeconds,
396	      distance: parseFloat(this.totalDistance),
397	      avgSpeed: parseFloat(this.avgSpeed),
398	      calories: parseInt(this.calories)
399	    }
400	
401	    try {
402	      await storage.get({
403	        key: 'rideHistory',
404	        success: (data) => {
405	          const history = JSON.parse(data || '[]')
406	          history.push(record)
407	          storage.set({
408	            key: 'rideHistory',
409	            value: JSON.stringify(history)
410	          })
411	        },
412	        fail: () => {
413	          storage.set({
414	            key: 'rideHistory',
415	            value: JSON.stringify([record])
416	          })
417	        }
418	      })
419	    } catch (err) {
420	      console.error('Save record error:', err)
421	    }
422	  },
423	
424	  showSafetyAlert(message) {
425	    this.showAlert = true
426	    this.alertMessage = message
427	    setTimeout(() => {
428	      this.showAlert = false
429	    }, 5000)
430	  }
431	}
432	</script>
