49	
50	const ZONE_LABEL = { rest: '偏低', normal: '正常', elevated: '偏高', peak: '偏高' };
51	const NORMAL = '#C9CDD2';
52	const ABN = '#FF263C';
53	const SPO2_LINE = '#FF2750';
