62	const ALL = [DATA_TYPES.HEART_RATE, DATA_TYPES.SPO2, DATA_TYPES.STRESS];
63	
64	/**
65	 * 个位数补零。
66	 * @param {number} n 0–59 的数
67	 * @returns {string} 两位字符串
68	 */
69	const pad2 = (n) => (n < 10 ? `0${n}` : `${n}`);
70	
71	/**
72	 * 当前时间 `HH:mm`。
73	 * @returns {string} 形如 `09:05`
74	 */
75	function nowHM() {
76	  const d = new Date();
