82	 * @param {number} v 血氧值（%）
83	 * @returns {{statusLabel: string, statusColor: string}} 状态标签与颜色
84	 */
85	function spo2Status(v) {
86	  return v >= 95
87	    ? { statusLabel: '正常', statusColor: NORMAL }
88	    : { statusLabel: '偏低', statusColor: ABN };
89	}
90	
91	/**
92	 * 压力状态判定（放松 / 正常 / 偏高 / 过高）。
93	 * @param {number} v 压力值
94	 * @returns {{statusLabel: string, statusColor: string}} 状态标签与颜色
95	 */
96	function stressStatus(v) {
97	  if (v < 30) return { statusLabel: '放松', statusColor: '#34D399' };
98	  if (v < 60) return { statusLabel: '正常', statusColor: '#2CE5C0' };
99	  if (v < 80) return { statusLabel: '偏高', statusColor: '#FF9F43' };
100	  return { statusLabel: '过高', statusColor: '#FF4D4D' };
101	}
