{
    lv_nuttx_uv_vsync_ctx_t * vsync_ctx = lv_event_get_user_data(e);
    void * param = lv_event_get_param(e);

    if(param) {
        if(vsync_ctx->vsync_req_count < 0) return;

        if(vsync_ctx->vsync_req_count == 0) {
