    }
    lv_timer_pause(vsync_ctx->vsync_timer);

    uv_loop_t * loop = uv_info->loop;

    if(loop != NULL) {
        vsync_ctx->fd = *(int *)(lv_intptr_t)lv_display_get_driver_data(uv_info->disp);
