          fps_flush_us += (uint64_t)(now.tv_sec - fps_t0.tv_sec) * 1000000 +
                          (now.tv_nsec - fps_t0.tv_nsec) / 1000;

          if (fps_frames == 0)
            {
              fps_win_start = fps_t0;
            }

          if (++fps_frames >= SF32LB_LCD_FPS_WINDOW)
            {
              uint64_t win_us =
                (uint64_t)(now.tv_sec - fps_win_start.tv_sec) * 1000000 +
                (now.tv_nsec - fps_win_start.tv_nsec) / 1000;

