static int lcddev_poll(FAR struct file *filep, FAR struct pollfd *fds,
                       bool setup)
{
  if (setup)
    {
      fds->revents |= (fds->events & POLLOUT);
      if (fds->revents != 0)
        {
          poll_notify(&fds, 1, POLLOUT);
        }
    }

  return OK;
}

