/* EPIC 硬件图形加速基准测试。
 *
 * 回答两个问题：
 *
 *   1. EPIC 能不能在 openvela/NuttX 上直接跑？
 *      思澈官方黄山派表盘示例走 EPIC 拿到丝滑效果，但那套代码依赖
 *      RT-Thread（rtthread.h / gui_app_fwk.h）。不过实测 bf0_hal_epic.c
 *      里 9 处 rtthread 引用全部是注释状态，HAL 层已被移植方清理成裸实现，
 *      只依赖 bf0_hal.h。所以理论上可以直接调，本程序验证这一点。
 *
 *   2. EPIC 比 CPU 快多少？
 *      实测背景：LVGL 软渲染下滑动只有 2.9 fps（纯色空卡片 7.1 fps），
 *      而 LCD 送屏仅占 17ms/帧，说明瓶颈在像素填充与合成。
 *      本程序用同一块 buffer 分别跑 CPU memset 和 EPIC 硬件填充，直接对比。
 *
 * 用法（NSH 下）：
 *
 *   epicbench            # 跑全部测试
 *
 * 输出示例：
 *
 *   EPIC_BENCH: init ok, instance=0x50080000
 *   EPIC_BENCH: fill  CPU=118ms  EPIC=6ms   speedup=19.6x
 *   EPIC_BENCH: blit  CPU=142ms  EPIC=9ms   speedup=15.8x
 */

#include <nuttx/config.h>

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <errno.h>
#include <inttypes.h>

#include <nuttx/cache.h>

#include "bf0_hal.h"
#include "bf0_hal_epic.h"

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* 屏幕分辨率，与 LCD 驱动一致（390×450 RGB565） */

#define BENCH_W      390
#define BENCH_H      450
#define BENCH_BPP    2
#define BENCH_BYTES  ((size_t)BENCH_W * BENCH_H * BENCH_BPP)

/* 每项测试重复次数，取平均以抵掉单次抖动 */

#define BENCH_ROUNDS 10

/****************************************************************************
 * Private Data
 ****************************************************************************/

static EPIC_HandleTypeDef g_epic;

/* EPIC 完成标志。HAL 的阻塞版接口内部自己轮询，这里只用于中断版验证。 */

static volatile bool g_epic_done;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: now_us
 *
 * Description:
 *   单调时钟当前值（微秒）。基准测试全部用它计时，避免 RTC 被调整影响。
 *
 ****************************************************************************/

static uint64_t now_us(void)
{
  struct timespec ts;

  if (clock_gettime(CLOCK_MONOTONIC, &ts) != 0)
    {
      return 0;
    }

  return (uint64_t)ts.tv_sec * 1000000 + ts.tv_nsec / 1000;
}

/****************************************************************************
 * Name: epic_cplt_cb
 *
 * Description:
 *   EPIC 传输完成回调，供中断版接口使用。
 *
 ****************************************************************************/

static void epic_cplt_cb(EPIC_HandleTypeDef *epic)
{
  (void)epic;
  g_epic_done = true;
}

/****************************************************************************
 * Name: bench_cpu_fill
 *
 * Description:
 *   CPU 填充基准：整屏填成单色。这是 LVGL 软渲染画纯色矩形时做的事，
 *   用 memset 已经是 CPU 能做到的最快路径（RGB565 高低字节相同时成立），
 *   所以这个数字是 CPU 侧的乐观上界。
 *
 * Returned Value:
 *   平均单次耗时（微秒）。
 *
 ****************************************************************************/

static uint64_t bench_cpu_fill(uint8_t *buf)
{
  uint64_t t0 = now_us();
  int i;

  for (i = 0; i < BENCH_ROUNDS; i++)
    {
      /* 0x1F 高低字节相同，memset 能正确铺出 RGB565 的蓝色 */

      memset(buf, 0x1f, BENCH_BYTES);
    }

  return (now_us() - t0) / BENCH_ROUNDS;
}

/****************************************************************************
 * Name: bench_epic_fill
 *
 * Description:
 *   EPIC 硬件填充基准，与 bench_cpu_fill 填同样大小的区域。
 *
 * Returned Value:
 *   平均单次耗时（微秒），失败返回 0。
 *
 ****************************************************************************/

static uint64_t bench_epic_fill(uint8_t *buf)
{
  EPIC_FillingCfgTypeDef cfg;
  uint64_t t0;
  int i;

  t0 = now_us();

  for (i = 0; i < BENCH_ROUNDS; i++)
    {
      HAL_EPIC_FillDataInit(&cfg);

      cfg.start       = buf;
      cfg.color_mode  = EPIC_COLOR_RGB565;
      cfg.width       = BENCH_W;
      cfg.height      = BENCH_H;
      cfg.total_width = BENCH_W;
      cfg.color_r     = 0x00;
      cfg.color_g     = 0x00;
      cfg.color_b     = 0xff;
      cfg.alpha       = 255;

      /* EPIC 是 DMA 类硬件，写之前得让它看到最新内存内容，
       * 完成后要让 CPU 看到硬件写入的结果。
       */

      up_clean_dcache((uintptr_t)buf, (uintptr_t)buf + BENCH_BYTES);

      if (HAL_EPIC_FillStart(&g_epic, &cfg) != HAL_OK)
        {
          printf("EPIC_BENCH: HAL_EPIC_FillStart failed, state=%d err=%" PRIu32 "\n",
                 (int)g_epic.State, g_epic.ErrorCode);
          return 0;
        }

      up_invalidate_dcache((uintptr_t)buf, (uintptr_t)buf + BENCH_BYTES);
    }

  return (now_us() - t0) / BENCH_ROUNDS;
}

/****************************************************************************
 * Name: bench_cpu_blit
 *
 * Description:
 *   CPU 整屏拷贝基准。滑动时 LVGL 要把卡片内容搬到新位置，本质是这个操作。
 *
 * Returned Value:
 *   平均单次耗时（微秒）。
 *
 ****************************************************************************/

static uint64_t bench_cpu_blit(uint8_t *dst, const uint8_t *src)
{
  uint64_t t0 = now_us();
  int i;

  for (i = 0; i < BENCH_ROUNDS; i++)
    {
      memcpy(dst, src, BENCH_BYTES);
    }

  return (now_us() - t0) / BENCH_ROUNDS;
}

/****************************************************************************
 * Name: bench_epic_blit
 *
 * Description:
 *   EPIC 整屏拷贝基准，对应 HAL_EPIC_Copy_IT。
 *   用中断版是因为 HAL 没提供阻塞版 Copy，需要自己等完成标志。
 *
 * Returned Value:
 *   平均单次耗时（微秒），失败返回 0。
 *
 ****************************************************************************/

static uint64_t bench_epic_blit(uint8_t *dst, uint8_t *src)
{
  EPIC_BlendingDataType s;
  EPIC_BlendingDataType d;
  uint64_t t0;
  int i;

  t0 = now_us();

  for (i = 0; i < BENCH_ROUNDS; i++)
    {
      memset(&s, 0, sizeof(s));
      memset(&d, 0, sizeof(d));

      s.data        = src;
      s.color_mode  = EPIC_COLOR_RGB565;
      s.width       = BENCH_W;
      s.height      = BENCH_H;
      s.total_width = BENCH_W;

      d.data        = dst;
      d.color_mode  = EPIC_COLOR_RGB565;
      d.width       = BENCH_W;
      d.height      = BENCH_H;
      d.total_width = BENCH_W;

      up_clean_dcache((uintptr_t)src, (uintptr_t)src + BENCH_BYTES);
      up_clean_dcache((uintptr_t)dst, (uintptr_t)dst + BENCH_BYTES);

      g_epic_done = false;
      g_epic.XferCpltCallback = epic_cplt_cb;

      if (HAL_EPIC_Copy_IT(&g_epic, &s, &d) != HAL_OK)
        {
          printf("EPIC_BENCH: HAL_EPIC_Copy_IT failed, state=%d err=%" PRIu32 "\n",
                 (int)g_epic.State, g_epic.ErrorCode);
          return 0;
        }

      /* 等硬件完成。设上限避免中断没接上时死等。 */

      {
        uint64_t deadline = now_us() + 500000;   /* 500ms */

        while (!g_epic_done && now_us() < deadline)
          {
            usleep(100);
          }

        if (!g_epic_done)
          {
            printf("EPIC_BENCH: copy timeout —— EPIC 中断可能没接上\n");
            return 0;
          }
      }

      up_invalidate_dcache((uintptr_t)dst, (uintptr_t)dst + BENCH_BYTES);
    }

  return (now_us() - t0) / BENCH_ROUNDS;
}

/****************************************************************************
 * Name: report
 *
 * Description:
 *   打印一项对比结果。加速比用定点算，避免引入浮点格式化。
 *
 ****************************************************************************/

static void report(const char *name, uint64_t cpu_us, uint64_t epic_us)
{
  if (epic_us == 0)
    {
      printf("EPIC_BENCH: %-5s CPU=%" PRIu64 "us  EPIC=失败\n", name, cpu_us);
      return;
    }

  {
    uint32_t ratio_x10 = (uint32_t)(cpu_us * 10 / epic_us);

    printf("EPIC_BENCH: %-5s CPU=%" PRIu64 "us  EPIC=%" PRIu64
           "us  speedup=%" PRIu32 ".%" PRIu32 "x\n",
           name, cpu_us, epic_us, ratio_x10 / 10, ratio_x10 % 10);
  }
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int main(int argc, FAR char *argv[])
{
  uint8_t *buf_a;
  uint8_t *buf_b;
  int ret = EXIT_FAILURE;

  (void)argc;
  (void)argv;

  printf("EPIC_BENCH: %dx%d RGB565, %zu bytes/frame, %d rounds\n",
         BENCH_W, BENCH_H, BENCH_BYTES, BENCH_ROUNDS);

  /* EPIC 是 DMA 类硬件，buffer 需要 cache line 对齐才能安全刷 cache */

  buf_a = memalign(64, BENCH_BYTES);
  buf_b = memalign(64, BENCH_BYTES);

  if (buf_a == NULL || buf_b == NULL)
    {
      printf("EPIC_BENCH: 分配 2×%zu 字节失败，内存不足\n", BENCH_BYTES);
      goto out;
    }

  memset(buf_a, 0xa5, BENCH_BYTES);
  memset(buf_b, 0x00, BENCH_BYTES);

  /* --- EPIC 初始化 -------------------------------------------------- */

  memset(&g_epic, 0, sizeof(g_epic));
  g_epic.Instance = EPIC;

  if (HAL_EPIC_Init(&g_epic) != HAL_OK)
    {
      printf("EPIC_BENCH: HAL_EPIC_Init 失败 err=%" PRIu32 "\n",
             g_epic.ErrorCode);
      printf("EPIC_BENCH: 结论 —— EPIC 在当前固件上起不来\n");
      goto out;
    }

  printf("EPIC_BENCH: init ok, instance=%p state=%d\n",
         g_epic.Instance, (int)g_epic.State);

  /* --- 填充对比 ----------------------------------------------------- */

  report("fill", bench_cpu_fill(buf_a), bench_epic_fill(buf_a));

  /* --- 拷贝对比 ----------------------------------------------------- */

  report("blit", bench_cpu_blit(buf_b, buf_a), bench_epic_blit(buf_b, buf_a));

  ret = EXIT_SUCCESS;

out:
  free(buf_a);
  free(buf_b);
  return ret;
}

