static bool epic_wait_done(const char *what)
{
  /* 轮询次数上限而不是掐时间：忙等期间不让出 CPU，实测连超时分支都跑不到，
   * 说明这个任务把核占满了，时钟推进拿不到。改成计数更可靠。
   *
   * EPIC 全屏操作在毫秒级，10 万次空转足够覆盖，卡死时也能及时报出来。
   */

  uint32_t spins = 0;

  while (!g_epic_done)
    {
      if (++spins > 100000)
        {
          printf("EPIC_BENCH: %s 等不到完成中断，state=%d err=%" PRIu32
                 " EOF_IRQ=0x%08" PRIx32 " SETTING=0x%08" PRIx32 "\n",
                 what, (int)g_epic.State, g_epic.ErrorCode,
                 (uint32_t)g_epic.Instance->EOF_IRQ,
                 (uint32_t)g_epic.Instance->SETTING);
          return false;
        }

      /* 每轮让一次 CPU，否则中断处理和时钟都推不动 */

      if ((spins & 0xff) == 0)
        {
          sched_yield();
        }
    }

  return true;
}

