static bool epic_wait_done(const char *what)
{
  /* 等 EPIC 空闲。判据是 handle 的 State 回到 READY，而不是等自己的
   * XferCpltCallback —— 实测 buffer 放对（SRAM）之后 State 已经能正常
   * 回到 READY=1，说明硬件跑完了，但用户回调没被调到。
   *
   * 原因是 HAL 内部用 IntXferCpltCallback 处理完成事件，XferCpltCallback
   * 只在特定 api_type 下转发；阻塞版接口（HAL_EPIC_FillStart）本身就自带
   * 轮询等待，返回时已经完成。所以这里只做兜底确认，不依赖中断路径。
   */

  uint32_t spins = 0;

  while (g_epic.State != HAL_EPIC_STATE_READY && !g_epic_done)
    {
      if (++spins > 200000)
        {
          printf("EPIC_BENCH: %s 未完成，state=%d err=%" PRIu32 "\n",
                 what, (int)g_epic.State, g_epic.ErrorCode);
          return false;
        }

      if ((spins & 0xff) == 0)
        {
          sched_yield();
        }
    }

  return true;
}

