/****************************************************************************
 * apps/examples/velaride/velaride.c
 *
 * VelaRide AI 卡片流（LVGL C 版）。
 *
 * 为什么不用快应用：
 *
 *   快应用版（vela-quickapp/src/pages/cards/index.ux）的 <swiper> 滑动由
 *   JS 引擎驱动 —— 手指移动要经过 QuickJS 算位移再通知渲染。实测帧率够
 *   （平均 62 fps，峰值 123），但帧间隔在 8ms~120ms 之间剧烈抖动，人眼
 *   对节奏不稳比对低帧率敏感，所以手感"不跟手"。
 *
 *   本程序用 LVGL 原生滚动：触摸事件直接进 LVGL，位移逐帧跟手，零 JS。
 *   做法照官方 watch_v9 的蜂窝菜单（example/multimedia/lvgl/watch_v9/src/
 *   gui_apps/main/app_mainmenu.c）—— LV_SCROLL_SNAP_CENTER 做吸附，
 *   LV_EVENT_SCROLL 里做逐帧变换。
 *
 * 用法（NSH 下）：
 *
 *   velaride
 *
 * 注意：LVGL 是单实例的，快应用（vapp）在跑时会占住显示驱动。
 * 运行前先 kill 掉 vapp，否则报 "disp refr_timer is NULL"。
 *
 * Licensed under the Apache License, Version 2.0 (the "License");
 * you may not use this file except in compliance with the License.
 * You may obtain a copy of the License at
 *
 *     http://www.apache.org/licenses/LICENSE-2.0
 *
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <unistd.h>

#include <lvgl/lvgl.h>

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* 屏幕实测 390×450 RGB565 */

#define SCR_W  390
#define SCR_H  450

#define CARD_COUNT 4

/* 卡片配色。与快应用版保持一致，方便对比手感差异。 */

#define COLOR_BG        lv_color_hex(0x0a0a0a)
#define COLOR_HOME      lv_color_hex(0x0f1729)
#define COLOR_RIDE      lv_color_hex(0x0d1f17)
#define COLOR_ALERT     lv_color_hex(0x241a12)
#define COLOR_REVIEW    lv_color_hex(0x1a1226)

#define COLOR_CYAN      lv_color_hex(0x38bdf8)
#define COLOR_GREEN     lv_color_hex(0x4ade80)
#define COLOR_AMBER     lv_color_hex(0xfbbf24)
#define COLOR_WHITE     lv_color_hex(0xffffff)
#define COLOR_MUTED     lv_color_hex(0x64748b)
#define COLOR_DIM       lv_color_hex(0x475569)
#define COLOR_TRACK     lv_color_hex(0x1e293b)

/* 休息提醒周期（秒）。进度条按这个算百分比。 */

#define REST_CYCLE_SEC (40 * 60)

/****************************************************************************
 * Private Types
 ****************************************************************************/

/* 一张卡片上需要按数据刷新的控件。不需要刷新的（标题、提示文字）
 * 建完就不再引用，所以不存指针。
 */

struct card_home_s
{
  lv_obj_t *clock;
  lv_obj_t *distance;
  lv_obj_t *duration;
  lv_obj_t *calories;
};

struct card_ride_s
{
  lv_obj_t *elapsed;
  lv_obj_t *speed;
  lv_obj_t *distance;
  lv_obj_t *bar;
  lv_obj_t *motion;
};

struct card_alert_s
{
  lv_obj_t *message;
  lv_obj_t *minutes;
};

struct card_review_s
{
  lv_obj_t *text;
};

struct velaride_s
{
  lv_obj_t *page;                 /* 承载卡片的滚动容器 */
  lv_obj_t *cards[CARD_COUNT];

  struct card_home_s   home;
  struct card_ride_s   ride;
  struct card_alert_s  alert;
  struct card_review_s review;

  uint32_t ride_sec;              /* 骑行秒数，驱动所有派生数据 */
};

/****************************************************************************
 * Private Data
 ****************************************************************************/

static struct velaride_s g_app;

/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: make_label
 *
 * Description:
 *   建一个标签的公共套路：设文本、颜色、字体，挂到父对象上。
 *
 * Input Parameters:
 *   parent - 父对象
 *   text   - 初始文本
 *   color  - 文字颜色
 *   font   - 字体，NULL 表示用继承的默认字体
 *
 * Returned Value:
 *   新建的标签对象。
 *
 ****************************************************************************/

static lv_obj_t *make_label(lv_obj_t *parent, const char *text,
                            lv_color_t color, const lv_font_t *font)
{
  lv_obj_t *label = lv_label_create(parent);

  lv_label_set_text(label, text);
  lv_obj_set_style_text_color(label, color, LV_PART_MAIN);

  if (font != NULL)
    {
      lv_obj_set_style_text_font(label, font, LV_PART_MAIN);
    }

  return label;
}

/****************************************************************************
 * Name: make_card
 *
 * Description:
 *   建一张整屏卡片。卡片本身不可滚动（滚动交给父容器），
 *   内部用竖向 flex 居中排布。
 *
 * Input Parameters:
 *   parent - 滚动容器
 *   bg     - 卡片背景色
 *
 * Returned Value:
 *   新建的卡片对象。
 *
 ****************************************************************************/

static lv_obj_t *make_card(lv_obj_t *parent, lv_color_t bg)
{
  lv_obj_t *card = lv_obj_create(parent);

  lv_obj_set_size(card, SCR_W, SCR_H);
  lv_obj_set_style_bg_color(card, bg, LV_PART_MAIN);
  lv_obj_set_style_bg_opa(card, LV_OPA_COVER, LV_PART_MAIN);
  lv_obj_set_style_border_width(card, 0, LV_PART_MAIN);
  lv_obj_set_style_radius(card, 0, LV_PART_MAIN);
  lv_obj_set_style_pad_all(card, 24, LV_PART_MAIN);

  /* 卡片自己不吃滚动手势，否则会和父容器抢事件 */

  lv_obj_remove_flag(card, LV_OBJ_FLAG_SCROLLABLE);

  lv_obj_set_flex_flow(card, LV_FLEX_FLOW_COLUMN);
  lv_obj_set_flex_align(card, LV_FLEX_ALIGN_CENTER,
                        LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);

  return card;
}

/****************************************************************************
 * Name: make_stat_row
 *
 * Description:
 *   建一行横排的数据格子（数值在上、单位在下）。
 *   返回的数组按传入顺序填好数值标签，调用方拿去刷新。
 *
 * Input Parameters:
 *   parent  - 父对象
 *   labels  - 单位文字数组
 *   out     - 输出：每个格子的数值标签
 *   count   - 格子数量
 *
 ****************************************************************************/

static void make_stat_row(lv_obj_t *parent, const char * const *labels,
                          lv_obj_t **out, int count)
{
  lv_obj_t *row = lv_obj_create(parent);
  int i;

  lv_obj_remove_style_all(row);
  lv_obj_set_size(row, LV_PCT(100), LV_SIZE_CONTENT);
  lv_obj_remove_flag(row, LV_OBJ_FLAG_SCROLLABLE);
  lv_obj_set_flex_flow(row, LV_FLEX_FLOW_ROW);
  lv_obj_set_flex_align(row, LV_FLEX_ALIGN_SPACE_EVENLY,
                        LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);

  for (i = 0; i < count; i++)
    {
      lv_obj_t *cell = lv_obj_create(row);

      lv_obj_remove_style_all(cell);
      lv_obj_set_size(cell, LV_SIZE_CONTENT, LV_SIZE_CONTENT);
      lv_obj_remove_flag(cell, LV_OBJ_FLAG_SCROLLABLE);
      lv_obj_set_flex_flow(cell, LV_FLEX_FLOW_COLUMN);
      lv_obj_set_flex_align(cell, LV_FLEX_ALIGN_CENTER,
                            LV_FLEX_ALIGN_CENTER, LV_FLEX_ALIGN_CENTER);

      out[i] = make_label(cell, "0", COLOR_WHITE, &lv_font_montserrat_24);
      make_label(cell, labels[i], COLOR_MUTED, NULL);
    }
}

input.old_string:
      out[i] = make_label(cell, "0", COLOR_WHITE, &lv_font_montserrat_24);
      make_label(cell, labels[i], COLOR_MUTED, NULL);
    }
}

input.new_string:
      out[i] = make_label(cell, "0", COLOR_WHITE, &lv_font_montserrat_24);
      make_label(cell, labels[i], COLOR_MUTED, NULL);
    }
}

/****************************************************************************
 * Name: build_card_home
 *
 * Description:
 *   卡片 1：首页概览。时钟 + 今日累计数据。
 *
 ****************************************************************************/

static void build_card_home(void)
{
  static const char * const units[] = { "km", "min", "kcal" };
  lv_obj_t *stats[3];
  lv_obj_t *card = make_card(g_app.page, COLOR_HOME);

  g_app.home.clock = make_label(card, "--:--", COLOR_WHITE,
                                &lv_font_montserrat_48);

  make_label(card, "VelaRide AI", COLOR_CYAN, &lv_font_montserrat_20);
  make_label(card, "Ride Safety Assistant", COLOR_MUTED, NULL);

  make_stat_row(card, units, stats, 3);
  g_app.home.distance = stats[0];
  g_app.home.duration = stats[1];
  g_app.home.calories = stats[2];

  make_label(card, "swipe up for ride data", COLOR_DIM, NULL);

  g_app.cards[0] = card;
}

/****************************************************************************
 * Name: build_card_ride
 *
 * Description:
 *   卡片 2：骑行中。计时、速度、距离、休息进度条。
 *
 ****************************************************************************/

static void build_card_ride(void)
{
  static const char * const units[] = { "km/h", "km" };
  lv_obj_t *stats[2];
  lv_obj_t *card = make_card(g_app.page, COLOR_RIDE);
  lv_obj_t *bar;

  make_label(card, "RIDING", COLOR_MUTED, NULL);

  g_app.ride.elapsed = make_label(card, "00:00:00", COLOR_WHITE,
                                  &lv_font_montserrat_48);

  make_stat_row(card, units, stats, 2);
  g_app.ride.speed = stats[0];
  g_app.ride.distance = stats[1];

  /* 休息周期进度条。用 lv_bar 而非自己画两个 div，
   * 它自带值变化的平滑过渡。
   */

  bar = lv_bar_create(card);
  lv_obj_set_size(bar, 260, 6);
  lv_obj_set_style_bg_color(bar, COLOR_TRACK, LV_PART_MAIN);
  lv_obj_set_style_bg_color(bar, COLOR_GREEN, LV_PART_INDICATOR);
  lv_obj_set_style_radius(bar, 3, LV_PART_MAIN);
  lv_obj_set_style_radius(bar, 3, LV_PART_INDICATOR);
  lv_bar_set_range(bar, 0, 100);
  lv_bar_set_value(bar, 0, LV_ANIM_OFF);
  g_app.ride.bar = bar;

  g_app.ride.motion = make_label(card, "idle", COLOR_DIM, NULL);

  g_app.cards[1] = card;
}

/****************************************************************************
 * Name: build_card_alert
 *
 * Description:
 *   卡片 3：安全提醒。
 *
 ****************************************************************************/

static void build_card_alert(void)
{
  lv_obj_t *card = make_card(g_app.page, COLOR_ALERT);

  make_label(card, "!", COLOR_AMBER, &lv_font_montserrat_48);
  make_label(card, "SAFETY", COLOR_MUTED, NULL);

  g_app.alert.message = make_label(card, "Take a 5 min break",
                                   COLOR_AMBER, &lv_font_montserrat_16);

  g_app.alert.minutes = make_label(card, "riding 0 min", COLOR_DIM, NULL);

  g_app.cards[2] = card;
}

/****************************************************************************
 * Name: build_card_review
 *
 * Description:
 *   卡片 4：AI 复盘。文字需要换行，所以显式设宽度加 WRAP 模式。
 *
 ****************************************************************************/

static void build_card_review(void)
{
  lv_obj_t *card = make_card(g_app.page, COLOR_REVIEW);

  make_label(card, "AI REVIEW", COLOR_MUTED, NULL);

  g_app.review.text = make_label(card,
    "Steady pace this session. Consider a break every 40 minutes.",
    lv_color_hex(0xe2e8f0), NULL);

  lv_obj_set_width(g_app.review.text, SCR_W - 60);
  lv_label_set_long_mode(g_app.review.text, LV_LABEL_LONG_WRAP);
  lv_obj_set_style_text_align(g_app.review.text, LV_TEXT_ALIGN_CENTER,
                              LV_PART_MAIN);

  make_label(card, "swipe to return", COLOR_DIM, NULL);

  g_app.cards[3] = card;
}

input.old_string:
  make_label(card, "swipe to return", COLOR_DIM, NULL);

  g_app.cards[3] = card;
}

input.new_string:
  make_label(card, "swipe to return", COLOR_DIM, NULL);

  g_app.cards[3] = card;
}

/****************************************************************************
 * Name: build_ui
 *
 * Description:
 *   搭建卡片流。
 *
 *   关键是滚动容器的配置 —— 这决定了跟手手感：
 *
 *   - LV_SCROLL_SNAP_CENTER：松手后自动吸附到最近的卡片中心，
 *     照官方 watch_v9 蜂窝菜单（app_mainmenu.c:1424）的做法
 *   - LV_DIR_VER：只吃竖向手势，避免横向误触
 *   - scrollbar OFF：手表屏幕上滚动条没意义
 *
 *   滚动过程由 LVGL 直接跟触摸事件走，不经过任何脚本层，
 *   所以能做到逐帧跟手。
 *
 ****************************************************************************/

static void build_ui(void)
{
  lv_obj_t *screen = lv_screen_active();
  lv_obj_t *page;

  lv_obj_set_style_bg_color(screen, COLOR_BG, LV_PART_MAIN);
  lv_obj_set_style_bg_opa(screen, LV_OPA_COVER, LV_PART_MAIN);
  lv_obj_remove_flag(screen, LV_OBJ_FLAG_SCROLLABLE);

  page = lv_obj_create(screen);
  lv_obj_remove_style_all(page);
  lv_obj_set_size(page, SCR_W, SCR_H);
  lv_obj_set_pos(page, 0, 0);

  /* 卡片竖排，之间不留缝 —— 每张恰好铺满一屏 */

  lv_obj_set_flex_flow(page, LV_FLEX_FLOW_COLUMN);
  lv_obj_set_style_pad_row(page, 0, LV_PART_MAIN);
  lv_obj_set_style_pad_all(page, 0, LV_PART_MAIN);

  /* 吸附到卡片中心 + 只允许竖滑 */

  lv_obj_set_scroll_snap_y(page, LV_SCROLL_SNAP_CENTER);
  lv_obj_set_scroll_dir(page, LV_DIR_VER);
  lv_obj_set_scrollbar_mode(page, LV_SCROLLBAR_MODE_OFF);

  g_app.page = page;

  build_card_home();
  build_card_ride();
  build_card_alert();
  build_card_review();

  /* 初始定位到第一张。ANIM_OFF 避免启动时看到一次滚动动画。 */

  lv_obj_scroll_to_view(g_app.cards[0], LV_ANIM_OFF);
}

/****************************************************************************
 * Name: update_tick
 *
 * Description:
 *   每秒刷新一次数据。
 *
 *   目前速度和距离是按骑行秒数模拟的（和快应用版一致），
 *   接真实传感器时替换 derive 部分即可，界面代码不用动。
 *
 ****************************************************************************/

static void update_tick(lv_timer_t *timer)
{
  char buf[64];
  time_t now;
  struct tm tm_now;
  uint32_t sec;
  uint32_t minutes;
  int percent;

  LV_UNUSED(timer);

  /* --- 时钟 --- */

  now = time(NULL);
  localtime_r(&now, &tm_now);
  snprintf(buf, sizeof(buf), "%02d:%02d", tm_now.tm_hour, tm_now.tm_min);
  lv_label_set_text(g_app.home.clock, buf);

  /* --- 骑行计时 --- */

  sec = ++g_app.ride_sec;
  minutes = sec / 60;

  snprintf(buf, sizeof(buf), "%02" PRIu32 ":%02" PRIu32 ":%02" PRIu32,
           sec / 3600, (sec % 3600) / 60, sec % 60);
  lv_label_set_text(g_app.ride.elapsed, buf);

  /* --- 派生数据（模拟，待接传感器）--- */

  snprintf(buf, sizeof(buf), "%" PRIu32 ".%" PRIu32,
           15 + (sec % 7), sec % 10);
  lv_label_set_text(g_app.ride.speed, buf);

  snprintf(buf, sizeof(buf), "%" PRIu32 ".%" PRIu32,
           sec * 4 / 1000, (sec * 4 / 100) % 10);
  lv_label_set_text(g_app.ride.distance, buf);

  lv_label_set_text(g_app.ride.motion,
                    (sec % 10) < 5 ? "riding" : "cruising");

  percent = (int)((uint64_t)sec * 100 / REST_CYCLE_SEC);
  if (percent > 100)
    {
      percent = 100;
    }

  /* ANIM_ON：每秒一次的值变化走平滑过渡，比直接跳更顺眼 */

  lv_bar_set_value(g_app.ride.bar, percent, LV_ANIM_ON);

  /* --- 提醒卡片 --- */

  snprintf(buf, sizeof(buf), "riding %" PRIu32 " min", minutes);
  lv_label_set_text(g_app.alert.minutes, buf);

  /* --- 今日累计（暂用固定值，待接持久化）--- */

  lv_label_set_text(g_app.home.distance, "12.5");
  lv_label_set_text(g_app.home.duration, "45");
  lv_label_set_text(g_app.home.calories, "180");
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int main(int argc, FAR char *argv[])
{
  lv_nuttx_dsc_t info;
  lv_nuttx_result_t result;

  LV_UNUSED(argc);
  LV_UNUSED(argv);

  /* LVGL 是单实例的。快应用（vapp）在跑时已经占住显示驱动，
   * 两个实例抢驱动会得到 "disp refr_timer is NULL"。
   */

  if (lv_is_initialized())
    {
      printf("velaride: LVGL already initialized (vapp running?).\n");
      printf("velaride: kill the vapp process first.\n");
      return EXIT_FAILURE;
    }

  lv_init();

  lv_nuttx_dsc_init(&info);
#ifdef CONFIG_LV_USE_NUTTX_LCD
  info.fb_path = "/dev/lcd0";
#endif
#ifdef CONFIG_LV_USE_NUTTX_TOUCHSCREEN
  info.input_path = "/dev/input0";
#endif

  lv_nuttx_init(&info, &result);

  if (result.disp == NULL)
    {
      printf("velaride: display init failed\n");
      return EXIT_FAILURE;
    }

  if (result.indev == NULL)
    {
      /* 没有触摸就只能看，不能滑 —— 提示但不退出 */

      printf("velaride: WARNING no input device, swipe unavailable\n");
    }

  build_ui();
  update_tick(NULL);
  lv_timer_create(update_tick, 1000, NULL);

  while (1)
    {
      uint32_t idle = lv_timer_handler();

      /* lv_timer_handler 返回距下次任务的毫秒数。返回 0 时给 1ms，
       * 避免空转把 CPU 占满 —— 滚动期间它会返回很小的值，
       * 所以不影响跟手。
       */

      usleep((idle ? idle : 1) * 1000);
    }

  return EXIT_SUCCESS;
}

