updateTime() {
  const now = new Date()
  const hh = String(now.getHours()).padStart(2, '0')
  const mm = String(now.getMinutes()).padStart(2, '0')
  const next = hh + ':' + mm
  // 只在真的变了才赋值。时钟精度是分钟，每秒写一次会白触发 59 次重渲染。
  if (next !== this.currentTime) {
    this.currentTime = next
  }
},

updateRide() {
  const s = this.rideSeconds
  const hh = String(Math.floor(s / 3600)).padStart(2, '0')
  const mm = String(Math.floor((s % 3600) / 60)).padStart(2, '0')
  const ss = String(s % 60).padStart(2, '0')
  this.rideTime = hh + ':' + mm + ':' + ss

  // 下面这些的精度都是分钟级或变化很慢，每秒重算重写没意义 ——
  // 每次赋值都会触发一次绑定更新和重渲染，滑动时这些开销直接叠在手感上。
  const minutes = Math.floor(s / 60)
  if (minutes !== this.rideMinutes) {
    this.rideMinutes = minutes
  }

  // 以 40 分钟为一个休息周期算进度
  const percent = Math.min(100, Math.floor((s / (40 * 60)) * 100))
  if (percent !== this.progressPercent) {
    this.progressPercent = percent
  }

  const motion = s % 10 < 5 ? '骑行中' : '缓行'
  if (motion !== this.motionText) {
    this.motionText = motion
  }

  const speed = (15 + (s % 7)).toFixed(1)
  if (speed !== this.currentSpeed) {
    this.currentSpeed = speed
  }

  const dist = (s * 0.004).toFixed(1)
  if (dist !== this.totalDistance) {
    this.totalDistance = dist
  }
}

