struct velaride_s
{
  lv_obj_t *page;                 /* 承载卡片的滚动容器 */
  lv_obj_t *cards[CARD_COUNT];

  struct card_home_s   home;
  struct card_ride_s   ride;
  struct card_alert_s  alert;
  struct card_review_s review;

  uint32_t ride_sec;              /* 骑行秒数，驱动所有派生数据 */

  /* 手势累加状态。照官方 watch_v9 蜂窝菜单的做法：
   * 按下时禁用 LVGL 自带滚动，PRESSING 期间只累加位移，
   * 到 REFR_START（渲染开始那一刻）才一次性应用。
   * 这样位移和渲染严格同步，帧间隔才均匀。
   */

  lv_point_t scroll_sum;
  bool scroll_actived;
};

/****************************************************************************
 * Name: refr_start_cb
 *
 * Description:
 *   渲染开始时应用累加的滚动位移。这是跟手手感的关键。
 *
 *   LVGL 默认滚动是"触摸事件一到就滚"，滚动时机和渲染时机不同步，
 *   帧间隔会抖（实测 8ms~120ms）。官方 watch_v9 的做法是把两者对齐：
 *   PRESSING 只累加不滚，等到 LV_EVENT_REFR_START 这一刻才
 *   `_lv_obj_scroll_by_raw()` 一次性应用。每帧只滚一次、正好在画之前，
 *   帧间隔自然均匀。
 *
 *   对应源码：example/multimedia/lvgl/watch_v9/src/gui_apps/main/
 *   app_mainmenu.c 的 refr_start_cb()（第 1099 行）。
 *
 ****************************************************************************/

static void refr_start_cb(lv_event_t *e)
{
  LV_UNUSED(e);

  if (g_app.scroll_actived)
    {
      lv_obj_scroll_by_bounded(g_app.page,
                               g_app.scroll_sum.x,
                               g_app.scroll_sum.y,
                               LV_ANIM_OFF);

      g_app.scroll_sum.x = 0;
      g_app.scroll_sum.y = 0;
    }
}

/****************************************************************************
 * Name: page_event_cb
 *
 * Description:
 *   容器手势处理。四个阶段照官方 watch_v9 的 mainmenu_cell_page_event_cb()：
 *
 *     PRESSED   关掉 SCROLLABLE，停掉正在跑的吸附动画，接管滚动
 *     PRESSING  累加位移，超过 scroll_limit 才算真滚动（防误触）
 *     RELEASED  恢复 SCROLLABLE，交回 LVGL 做吸附
 *     （位移的实际应用在 refr_start_cb 里）
 *
 ****************************************************************************/

static void page_event_cb(lv_event_t *e)
{
  lv_event_code_t code = lv_event_get_code(e);

  if (code == LV_EVENT_PRESSED)
    {
      /* 接管滚动：禁掉 LVGL 自带的，并掐掉可能在跑的吸附动画，
       * 否则动画会和手指位移打架。
       */

      lv_obj_remove_flag(g_app.page, LV_OBJ_FLAG_SCROLLABLE);
      lv_anim_delete(g_app.page, NULL);
    }
  else if (code == LV_EVENT_PRESSING)
    {
      lv_indev_t *indev = lv_indev_active();
      lv_point_t vect;

      if (indev == NULL)
        {
          return;
        }

      /* 本帧的手指位移增量 */

      lv_indev_get_vect(indev, &vect);

      g_app.scroll_sum.x += vect.x;
      g_app.scroll_sum.y += vect.y;

      /* 超过 scroll_limit 才认定为滚动，避免点按被当成滑动。
       * 一旦认定就保持，否则手指停顿会中断滚动。
       */

      if (LV_ABS(g_app.scroll_sum.y) > lv_indev_get_scroll_limit(indev) ||
          LV_ABS(g_app.scroll_sum.x) > lv_indev_get_scroll_limit(indev) ||
          g_app.scroll_actived)
        {
          g_app.scroll_actived = true;

          /* 标脏，触发下一次渲染 —— 实际位移在 refr_start_cb 里应用 */

          lv_obj_invalidate(g_app.page);
        }
    }
  else if (code == LV_EVENT_RELEASED ||
           code == LV_EVENT_PRESS_LOST ||
           code == LV_EVENT_CLICKED)
    {
      /* 交回 LVGL：恢复 SCROLLABLE 后 snap 会把最近的卡片吸附到中心 */

      lv_obj_add_flag(g_app.page, LV_OBJ_FLAG_SCROLLABLE);

      if (g_app.scroll_actived)
        {
          lv_obj_scroll_to_view(nearest_card(), LV_ANIM_ON);
        }

      g_app.scroll_actived = false;
      g_app.scroll_sum.x = 0;
      g_app.scroll_sum.y = 0;
    }
}

/****************************************************************************
 * Name: nearest_card
 *
 * Description:
 *   找离屏幕中心最近的卡片，松手后吸附到它。
 *   对应官方的 mainmenu_cell_predict_focus_icon()。
 *
 * Returned Value:
 *   最近的卡片对象，找不到时返回第一张。
 *
 ****************************************************************************/

static lv_obj_t *nearest_card(void)
{
  lv_obj_t *best = g_app.cards[0];
  int32_t best_dist = INT32_MAX;
  int32_t scr_mid = SCR_H / 2;
  int i;

  for (i = 0; i < CARD_COUNT; i++)
    {
      lv_area_t area;
      int32_t mid;
      int32_t dist;

      lv_obj_get_coords(g_app.cards[i], &area);
      mid = (area.y1 + area.y2) / 2;
      dist = LV_ABS(mid - scr_mid);

      if (dist < best_dist)
        {
          best_dist = dist;
          best = g_app.cards[i];
        }
    }

  return best;
}

